import type { HTMLAttributes, ReactNode } from "react";
import { cx } from "../utils/cx";

export type AppShellProps = HTMLAttributes<HTMLDivElement> & {
  /** Usually a <Dock placement="fixed">. */
  sidebar?: ReactNode;
  /** Quick tools pinned top-right (search, a primary action). Moves to the bottom on small screens. */
  toolbar?: ReactNode;
  /** Accessible name of the toolbar region. Default "Page tools". */
  toolbarLabel?: string;
  /** Which edge the sidebar is on, so the stage clears it. Match the Dock's `side`. Default `left`. */
  sidebarSide?: "left" | "right";
  /** Optional backdrop (an <Atmosphere />). */
  backdrop?: ReactNode;
  /** One-time arrival choreography: a black curtain lifts, the dock slides in, the page rises. */
  entrance?: "none" | "curtain" | "fade";
  /** id of the <main> landmark, for the skip link. */
  mainId?: string;
  children: ReactNode;
};

/** Page frame: sidebar, toolbar, and a main stage that clears the sidebar. Server-compatible. */
export function AppShell({
  sidebar,
  toolbar,
  toolbarLabel = "Page tools",
  backdrop,
  sidebarSide = "left",
  entrance = "none",
  mainId = "main",
  className,
  children,
  ...rest
}: AppShellProps) {
  return (
    <div
      {...rest}
      className={cx("hm-shell", className)}
      data-entrance={entrance === "none" ? undefined : entrance}
      data-sidebar={sidebarSide === "right" ? "right" : undefined}
    >
      <a className="hm-skip" href={`#${mainId}`}>
        Skip to content
      </a>
      {backdrop}
      {sidebar}
      {toolbar ? (
        <div className="hm-shell-toolbar" role="region" aria-label={toolbarLabel}>
          {toolbar}
        </div>
      ) : null}
      <main id={mainId} className="hm-shell-stage">
        {children}
      </main>
    </div>
  );
}

export type PageProps = HTMLAttributes<HTMLDivElement> & {
  /** Content width: `content` (62rem, the studio column) or `wide`. */
  width?: "content" | "wide";
};

/** The page column inside the stage: the studio's measured width and vertical rhythm. */
export function Page({ width = "content", className, ...rest }: PageProps) {
  return <div {...rest} className={cx("hm-page", className)} data-width={width} />;
}

/**
 * A deep-space backdrop with a deliberate composition: a violet-to-cyan nebula on the diagonal, a calm center, and
 * two star layers. It drifts very slowly and shifts a few pixels against the pointer (fed by `LightField`), and holds
 * still under reduced motion. Server-compatible.
 */
export function Atmosphere({ className, ...rest }: HTMLAttributes<HTMLDivElement>) {
  return (
    <div aria-hidden="true" {...rest} className={cx("hm-atmosphere", className)}>
      <span className="hm-sky-nebula" />
      <span className="hm-sky-stars" data-depth="far" />
      <span className="hm-sky-stars" data-depth="near" />
    </div>
  );
}
